{{"language":"Solidity","sources":{"contracts/UniswapV2Router02.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity =0.6.6;

import "./interfaces/IRouterHelper.sol";

contract UniswapV2Router02 is IRouterHelper {
    address public immutable factory;
    address public immutable WETH;

    bytes32 internal constant INIT_CODE_PAIR_HASH =
        hex'96e8ac4277198ff8b6f785478aa9a39f403cb768dd02cbee326c3e7da348845f';

    constructor(address _factory, address _WETH) public {
        factory = _factory;
        WETH = _WETH;
    }

    function pairFor(address tokenA, address tokenB) external view override returns (address pair) {
        (address token0, address token1) = tokenA < tokenB ? (tokenA, tokenB) : (tokenB, tokenA);
        pair = address(uint(keccak256(abi.encodePacked(
            hex'ff',
            factory,
            keccak256(abi.encodePacked(token0, token1)),
            INIT_CODE_PAIR_HASH
        ))));
    }

    function quote(uint amountA, uint reserveA, uint reserveB) external view override returns (uint amountB) {
        require(amountA > 0 && reserveA > 0 && WETH != address(0), "Router: INVALID");
        amountB = (amountA * reserveB) / reserveA;
    }
}
"},"contracts/interfaces/IRouterHelper.sol":{"content":"// SPDX-License-Identifier: MIT
